package org.tsitle.rtsp.packets.rtp;

import org.junit.jupiter.api.Test;
import org.tsitle.rtsp.buffers.BufferExt;
import org.tsitle.rtsp.security.*;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class DebugRtpPacketTest {

	@Test
	public void debugRtpPacket1() {
		final BufferExt tmpBufferExt = BufferExt.decodeHexString("80 00 bf 65 a8 9f ed 09 f2 3d d9 09");
		RtpBaseContainerInfo rbci = RtpPacketContainerBase.parsePacketHeader(tmpBufferExt);
		RtpPacketContainerBase tmpRtpPacket = new RtpPacketContainerBase(rbci.payloadType(), tmpBufferExt);

		System.out.println("RTP packet header: " + tmpRtpPacket);

		assertEquals(0xF23DD909, tmpRtpPacket.getSsrcId());
	}

	private void decryptPacketBuffer(
				String senderMikeyMsgB64,
				BufferExt encryptedSrtpPktBuf
			) throws Exception {
		SrtxpKmd kmdOrg = MikeyParser.parseMickeyMsgIntoKmd(senderMikeyMsgB64);
		//System.out.println("KMD Original: " + kmdOrg);

		/*
		 * !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
		 * The Gstreamer plugin SRTPENC has a bug regarding the Auth Key signaling.
		 * The MIKEY message that the Gstreamer RTSP server sends contains an incorrect Auth Key length of 10 bytes.
		 * The actual Auth Key length that is being used is 20 bytes.
		 * !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
		 *
		 * Code from libSRTP (srtp/srtp.c:3163):
		 *
		 * void srtp_crypto_policy_set_rtp_default(srtp_crypto_policy_t *p)
		 * {
		 *     p->cipher_type = SRTP_AES_ICM_128;
		 *     p->cipher_key_len = SRTP_AES_ICM_128_KEY_LEN_WSALT;  // default 128 bits per RFC-3711
		 *     p->auth_type = SRTP_HMAC_SHA1;
		 *     p->auth_key_len = 20;  // default 160 bits per RFC-3711
		 *     p->auth_tag_len = 10;  // default 80 bits per RFC-3711
		 *     p->sec_serv = sec_serv_conf_and_auth;
		 * }
		 *
		 * In fact, in that library the Auth Key length is always 20 bytes. The Auth Tag length can be 10 bytes (default)
		 * or 4 bytes.
		 *
		 * Then in the Gstreamer code (subprojects/gst-plugins-base/gst-libs/gst/sdp/gstmikey.c:2476):
		 *
		 * static gboolean
		 * auth_key_length_from_auth_cipher_name (const gchar * auth, const gchar * cipher, guint8 * length)
		 * {
		 *   if (g_strcmp0 (cipher, "aes-128-gcm") == 0
		 *       || g_strcmp0 (cipher, "aes-256-gcm") == 0) {
		 *     *length = 0;
		 *   } else {
		 *     if (g_strcmp0 (auth, "hmac-sha1-32") == 0) {
		 *       *length = HMAC_32_KEY_LEN;  // 4 bytes
		 *     } else if (g_strcmp0 (auth, "hmac-sha1-80") == 0) {
		 *       *length = HMAC_80_KEY_LEN;  // 10 bytes
		 *     } else {
		 *       GST_ERROR ("authentication algorithm '%s' not supported", auth);
		 *       return FALSE;
		 *     }
		 *   }
		 *   return TRUE;
		 * }
		 *
		 * We can see that the Auth Key length is set to 4 bytes for HMAC-SHA1-32 and 10 bytes for HMAC-SHA1-80.
		 *
		 * See my Merge Request
		 *   https://gitlab.freedesktop.org/gstreamer/gstreamer/-/merge_requests/11629
		 */
		SrtxpKmd kmdMod = new SrtxpKmd(
				false,
				kmdOrg.encrKeyLen(),
				kmdOrg.masterKey(),
				kmdOrg.masterSalt(),
				SrtxpKmd.DEFAULT_AUTH_KEY_LEN,  // <-- workaround for Gstreamer/SRTPENC bug
				kmdOrg.authTagLen(),
				kmdOrg.mki(),
				kmdOrg.ssrcId(),
				kmdOrg.kdr()
			);
		System.out.println("KMD Modified: " + kmdMod);
		final SrtpContextInbound receiverCtx = new SrtpContextInbound(kmdMod);

		RtpBaseContainerInfo rbci = RtpPacketContainerBase.parsePacketHeader(encryptedSrtpPktBuf);

		final BufferExt decryptedRtpPktBuf = new BufferExt();

		receiverCtx.unprotectSrtp(encryptedSrtpPktBuf, rbci.sequenceNumber(), rbci.ssrcId(), decryptedRtpPktBuf);

		// change the payload type to a value that matches our own enum values (Gstreamer uses 96, but we use 112)
		byte tmpByte = (byte)((byte)(decryptedRtpPktBuf.get(1) & 0x80) | (byte)(RtpPacketType.V_H264.getValue() & 0x7F));
		decryptedRtpPktBuf.set(1, tmpByte);

		//
		RtpPacketContainerBase tmpRtpPacket = new RtpPacketContainerBase(RtpPacketType.V_H264, decryptedRtpPktBuf);
		assertEquals(rbci.ssrcId(), tmpRtpPacket.getSsrcId());

		//
		RtpPacketH264 tmpRtpPacketH264 = new RtpPacketH264(decryptedRtpPktBuf);
		final BufferExt decryptedPayloadBuf = new BufferExt();
		tmpRtpPacketH264.getRawInnerPayloadData(decryptedPayloadBuf);
		System.out.println("RTP packet header: " + tmpRtpPacketH264);
		System.out.println("RTP packet buffer: " + decryptedPayloadBuf);
	}

	@Test
	public void debugRtpPacket2() throws Exception {
		/*
		 * This MIKEY message was generated by Gstreamer RTSP server with SRTP enabled
		 */
		final String senderMikeyMsgB64 = "AQAFACaRl84BAAAzw67DAAAAAAsA7a8VnK7Zi/cKENfMVVHi7KyMQZGCIInIa/cBAAAAFQABAQEBEAIBAQMBCgcBAQgBAQoBAQAAACIAIAAeVg+mWi59yl1d0r37sGd4pSMNlx3yT3XKCp+7vRqHAA==";
		/*
		 * This MIKEY message was generated by OpenRTSP client
		 */
		//final String recvMikeyMsgB64 = "AQAFAJSUtQoBAADSrbPoAAAAAAsA7a8VnK72tdQKEDnkpgvkt4NVH3NJydox7pQBAAAAGwABAQEBEAIBAQMBFAQBDgcBAQgBAQoBAQsBCgAAACcAIQAehjaDliVpRkjR6OMAnPhiw1PnMROnq9iFmjU1Vz8TBLbHxJsA";

		/*
		 * This SRTP packet was encrypted by Gstreamer RTSP server with SRTP enabled
		 */
		final BufferExt encryptedSrtpPktBuf = BufferExt.decodeHexString("80600bbefe2fb9d633c3aec3a623206cf390cc5556f6cda4f494cc576ed3151d85219564537e4708f8ed1d50db6fa03b1b82925e");

		/*
		 * Decrypted payload: 0x640028ACD940780227E5C05A808080A0000003002000000791E30632C0
		 * Confirmed to be valid - even though it occurs at the end of the input file instead of the beginning
		 */
		decryptPacketBuffer(senderMikeyMsgB64, encryptedSrtpPktBuf);
	}

	@Test
	public void debugRtpPacket3() throws Exception {
		/*
		 * This MIKEY message was generated by Gstreamer RTSP server with SRTP enabled
		 */
		final String senderMikeyMsgB64 = "AQAFAIr5ko0BAADtbhPoAAAAAAsA7a8Z/sk9yLgKEEUmWVOfsoGWV+nYP57lLbgBAAAAFQABAQEBEAIBAQMBCgcBAQgBAQoBAQAAACIAIAAeHk5Jg1HXImt7MSxAbY9sxfBctlVjN8vdyaPukSWdAA==";
		/*
		 * This MIKEY message was generated by Gstreamer client
		 */
		//final String recvMikeyMsgB64 = "AQAFAPJKSLwBAABS7vZZAAAAAAsA7a8Z/sllbu8KEMVYp3GsOCm1il+dRQSRh1kBAAAAFQABAQEBEAIBAQMBCgcBAQgBAQoBAQAAACIAIAAekblOeoVRKQgzfkAWYb7VzwNKj13GuoVWMUIwVCouAA==";

		// -----

		/*
		 * This SRTP packet was encrypted by Gstreamer RTSP server with SRTP enabled
		 */
		final BufferExt encryptedSrtpPktBuf_no1 = BufferExt.decodeHexString("80601036a4d48408ed6e13e861b8844656b89a48f60e58065a47cb2cd1098f16e87f96eb99d876c536ec1921d01e85fb960007f1");

		/*
		 * Decrypted payload: 0x640028ACD940780227E5C05A808080A0000003002000000791E30632C0
		 * Confirmed to be valid - even though it occurs at the end of the input file instead of the beginning
		 */
		decryptPacketBuffer(senderMikeyMsgB64, encryptedSrtpPktBuf_no1);

		// -----

		/*
		 * This SRTP packet was encrypted by Gstreamer RTSP server with SRTP enabled
		 */
		final BufferExt encryptedSrtpPktBuf_no2 = BufferExt.decodeHexString("");

		/*
		 * Decrypted payload: 
		 * Confirmed to be valid
		 */
		decryptPacketBuffer(senderMikeyMsgB64, encryptedSrtpPktBuf_no2);

		// -----

		/*
		 * This SRTP packet was encrypted by Gstreamer RTSP server with SRTP enabled
		 */
		final BufferExt encryptedSrtpPktBuf_no3 = BufferExt.decodeHexString("");

		/*
		 * Decrypted payload: 
		 * Confirmed to be valid
		 */
		decryptPacketBuffer(senderMikeyMsgB64, encryptedSrtpPktBuf_no3);
	}

}
